// DomainIR -> TS module source. The output is a plain object literal typed as DomainIR.
import type { DomainIR } from '../../src/htn-planner/htn/ir'
import type { WorldState } from '../../src/htn-planner/htn/world-state'

export interface EmitOptions {
  /**
   * Module specifier for the `import type { DomainIR }` line, relative to the generated file.
   * Default '../htn/ir' (a module in a sibling folder of src/htn-planner/htn, e.g. src/htn-planner/npc/x.ts; the CLI computes it from the output path).
   */
  irImportPath?: string
  /** Header comment lines (without `//`), e.g. the source domain path. */
  header?: string[]
}

const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/
const MAX_INLINE = 110

// Single-quoted like the repo's prettier config; JSON escaping covers backslashes and control characters.
function quote(text: string): string {
  return `'${JSON.stringify(text).slice(1, -1).replace(/\\"/g, '"').replace(/'/g, "\\'")}'`
}

function scalar(value: unknown): string {
  if (typeof value === 'number') return Object.is(value, -0) ? '-0' : String(value)
  if (typeof value === 'string') return quote(value)
  return JSON.stringify(value)
}

function serialize(value: unknown, indent: string): string {
  if (value === null || typeof value !== 'object') return scalar(value)
  const inner = indent + '  '
  if (Array.isArray(value)) {
    if (value.length === 0) return '[]'
    const parts = value.map(v => serialize(v, inner))
    const flat = `[${parts.join(', ')}]`
    if (flat.length + indent.length <= MAX_INLINE && !flat.includes('\n')) return flat
    return `[\n${parts.map(p => inner + p).join(',\n')}\n${indent}]`
  }
  const entries = Object.entries(value as Record<string, unknown>).filter(([, v]) => v !== undefined)
  if (entries.length === 0) return '{}'
  const parts = entries.map(([k, v]) => `${IDENT.test(k) ? k : quote(k)}: ${serialize(v, inner)}`)
  const flat = `{ ${parts.join(', ')} }`
  if (flat.length + indent.length <= MAX_INLINE && !flat.includes('\n')) return flat
  return `{\n${parts.map(p => inner + p).join(',\n')}\n${indent}}`
}

/**
 * Render a WorldState as a TS module: `export const <exportName>: WorldFacts = [[name, row], ...]`, loaded at
 * runtime with addFacts(world, ...). `options.irImportPath` is the specifier of the runtime folder's world-state
 * module (default '../htn/world-state').
 */
export function emitWorldStateModule(world: WorldState, exportName: string, options: EmitOptions = {}): string {
  if (!IDENT.test(exportName)) throw new Error(`htn: invalid export name '${exportName}'`)
  const importPath = options.irImportPath ?? '../htn/world-state'
  const facts: unknown[] = []
  for (const k of world.tableKeys()) {
    const slash = k.lastIndexOf('/')
    for (const row of world.rows(k.slice(0, slash), Number(k.slice(slash + 1)))) facts.push([k.slice(0, slash), row])
  }
  const header = ['Generated by tools/htn (npm run htn:compile). Do not edit by hand.', ...(options.header ?? [])]
  return (
    header.map(line => `// ${line}`).join('\n') +
    `\nimport type { WorldFacts } from '${importPath}'\n\n` +
    `export const ${exportName}: WorldFacts = ${serialize(facts, '')}\n`
  )
}

export function emitDomainModule(ir: DomainIR, exportName: string, options: EmitOptions = {}): string {
  if (!IDENT.test(exportName)) throw new Error(`htn: invalid export name '${exportName}'`)
  const importPath = options.irImportPath ?? '../htn/ir'
  const header = ['Generated by tools/htn (npm run htn:compile). Do not edit by hand.', ...(options.header ?? [])]
  return (
    header.map(line => `// ${line}`).join('\n') +
    `\nimport type { DomainIR } from '${importPath}'\n\n` +
    `export const ${exportName}: DomainIR = ${serialize(ir, '')}\n`
  )
}
